import { copyFile, mkdir, realpath, rm, stat } from 'node:fs/promises';
import { basename, extname, isAbsolute, join, relative } from 'node:path';
import { run } from './exec.ts';
import { skillBody } from './skills.ts';

/**
 * The verification agent follows the repo's own verification skill, as generated by pstack's
 * `create-verification-skill`: a `verify-<app>` skill that launches the real app, drives it like a user, asserts on
 * what it shows and captures evidence, with a feature map of user-facing features. How to verify differs per project,
 * so the skill belongs to the project; phat-mode finds it and runs it.
 */
export type VerifySkill = {
  name: string;
  /** Repo-relative directory, e.g. `.agents/skills/verify-phatty-lingo`. */
  dir: string;
  description: string;
  /** SKILL.md without front matter, from the commit the workspace is based on. */
  text: string;
  /** The feature map index (features/README.md), if there is one. */
  featureMap: string | undefined;
};

export const SKILL_ROOTS = ['.agents/skills', '.claude/skills', '.cursor/skills'];
const SKILL_FILE = /^(\.agents|\.claude|\.cursor)\/skills\/(verify-[^/]+)\/SKILL\.md$/;

/** A path inside a verify skill that only humans may change: everything except the feature map. */
export function isProtectedSkillPath(path: string): boolean {
  const match = /^(?:\.agents|\.claude|\.cursor)\/skills\/verify-[^/]+(\/.*)?$/.exec(path.replaceAll('\\', '/'));
  if (match === null) return false;
  return !(match[1] ?? '').startsWith('/features/');
}

/** The feature map, which the implementer may update when it changes behaviour on purpose (the skill says so). */
export const isFeatureMapPath = (path: string) =>
  /^(?:\.agents|\.claude|\.cursor)\/skills\/verify-[^/]+\/features\//.test(path.replaceAll('\\', '/'));

const frontMatterField = (text: string, field: string) => {
  const front = /^---\n([^]*?)\n---/.exec(text)?.[1] ?? '';
  const value = new RegExp(`^${field}:\\s*(.+)$`, 'm').exec(front)?.[1]?.trim() ?? '';
  return value.replace(/^(["'])(.*)\1$/, '$2');
};

const git = (workspace: string, args: string[]) => run('git', args, { cwd: workspace, allowFailure: true });

/**
 * The repo's verify skills at `ref` (the commit the workspace is based on), never from the working tree. A skill linked
 * from another root (e.g. .claude/skills/x → .agents/skills/x) is a symlink in git, so it is found once.
 */
export async function findVerifySkills(workspace: string, ref = 'HEAD'): Promise<VerifySkill[]> {
  const listed = await git(workspace, ['ls-tree', '-r', '--name-only', ref, '--', ...SKILL_ROOTS]);
  if (listed.code !== 0) return [];
  const skills = new Map<string, VerifySkill>();
  for (const path of listed.stdout.split('\n')) {
    const match = SKILL_FILE.exec(path.trim());
    if (match === null || skills.has(match[2]!)) continue;
    const dir = path.trim().slice(0, -'/SKILL.md'.length);
    const text = (await git(workspace, ['show', `${ref}:${path.trim()}`])).stdout;
    const map = await git(workspace, ['show', `${ref}:${dir}/features/README.md`]);
    skills.set(match[2]!, {
      name: frontMatterField(text, 'name') || match[2]!,
      dir,
      description: frontMatterField(text, 'description'),
      text: skillBody(text),
      featureMap: map.code === 0 ? map.stdout : undefined,
    });
  }
  return [...skills.values()];
}

/** Paths changed in the workspace since `ref`: modified, added or deleted, tracked or not. */
async function changedPaths(workspace: string, ref: string): Promise<string[]> {
  const tracked = await git(workspace, ['diff', '--name-only', ref, '--', ...SKILL_ROOTS]);
  const untracked = await git(workspace, ['ls-files', '--others', '--exclude-standard', '--', ...SKILL_ROOTS]);
  return [...new Set([...tracked.stdout.split('\n'), ...untracked.stdout.split('\n')].map((line) => line.trim()))]
    .filter((line) => line !== '')
    .sort();
}

/**
 * Undo any change to a verify skill's protected files (its SKILL.md, scripts, everything but the feature map), so the
 * verification runs exactly as the repo defines it, whatever the implementer did. Returns the paths it reverted.
 */
export async function restoreProtectedSkillFiles(workspace: string, ref = 'HEAD'): Promise<string[]> {
  const reverted: string[] = [];
  for (const path of await changedPaths(workspace, ref)) {
    if (!isProtectedSkillPath(path)) continue;
    const inRef = await git(workspace, ['cat-file', '-e', `${ref}:${path}`]);
    if (inRef.code === 0) {
      await run('git', ['checkout', ref, '--', path], { cwd: workspace });
    } else {
      // Added by the implementer: drop it from the index and the disk.
      await git(workspace, ['rm', '--cached', '--quiet', '--ignore-unmatch', '--', path]);
      await rm(join(workspace, path), { force: true, recursive: true });
    }
    reverted.push(path);
  }
  return reverted;
}

/** Feature map files this change touches. */
export async function changedFeatureMap(workspace: string, ref = 'HEAD'): Promise<string[]> {
  return (await changedPaths(workspace, ref)).filter(isFeatureMapPath);
}

// ─── Report ─────────────────────────────────────────────────────────────────

export type FeatureResult = {
  /** The feature file's name, e.g. `learning-path`. */
  feature: string;
  subFeatures: string[];
  /** verified: proved on the change. failed: a check failed. not_verified: needs a capability the harness lacks. */
  status: 'verified' | 'failed' | 'not_verified';
  /** For failed: the same check also fails on the base branch, so this change did not cause it. */
  preExisting: boolean;
  detail: string;
  /** Checks run on the change, each with its result, e.g. `ok: expect.sh label "HSK 1"`. */
  checks: string[];
  /** Absolute evidence paths from the run on the base branch; empty for a new feature. */
  before: string[];
  /** Absolute evidence paths from the run on the change. */
  after: string[];
};

export type VerificationReport = {
  summary: string;
  /** Why there is no before run, when there is none (e.g. every feature is new). Empty otherwise. */
  beforeNote: string;
  features: FeatureResult[];
  /** Where the feature map no longer matches an intended change: for /maintain-verification-skill. */
  drift: string[];
  /** Why verification could not run at all (e.g. no simulator). Empty when it ran. */
  couldNotRun: string;
};

/** Failures this change caused: the implementer must fix them. */
export const newFailures = (report: VerificationReport) =>
  report.couldNotRun.trim() !== '' ? [] : report.features.filter((result) => result.status === 'failed' && !result.preExisting);

/** What phat-mode records for the pull request. */
export type Verification =
  | { kind: 'skipped'; reason: string }
  | {
      kind: 'ran';
      skill: string;
      round: number;
      /** null when the verifier did not report. Evidence paths point at phat-mode's copies. */
      report: VerificationReport | null;
      /** Protected skill files the implementer changed, reverted before verifying. */
      reverted: string[];
      /** Feature map files this change edits. */
      featureMapChanged: string[];
      /** New failures were still open after the last round. */
      unresolved: boolean;
    };

// ─── Evidence ───────────────────────────────────────────────────────────────

/** Evidence phat-mode publishes: images, accessibility trees, logs and text. Anything else is left out. */
export const EVIDENCE_TYPES = ['.png', '.jpg', '.jpeg', '.gif', '.webp', '.json', '.log', '.txt', '.md'];
export const IMAGE_TYPES = ['.png', '.jpg', '.jpeg', '.gif', '.webp'];
const MAX_EVIDENCE_BYTES = 20 * 1024 * 1024;

const inside = (root: string, path: string) => {
  const rel = relative(root, path);
  return rel !== '' && !rel.startsWith('..') && !isAbsolute(rel);
};

/**
 * Copy the evidence a report names into phat-mode's own directory, and point the report at the copies. Only regular
 * files of an evidence type inside the given checkouts are taken, so an agent cannot get phat-mode to publish anything
 * else (credentials, files elsewhere on the machine). Returns the report with copied paths and what was left out.
 */
export async function collectEvidence(
  report: VerificationReport,
  options: { roots: readonly string[]; destination: string },
): Promise<{ report: VerificationReport; skipped: string[] }> {
  const roots = await Promise.all(options.roots.map((root) => realpath(root).catch(() => root)));
  const skipped: string[] = [];
  const copies = new Map<string, string>();
  let counter = 0;

  async function copy(path: string, side: 'before' | 'after', feature: string): Promise<string | undefined> {
    const key = `${side}:${path}`;
    if (copies.has(key)) return copies.get(key);
    const real = isAbsolute(path) ? await realpath(path).catch(() => undefined) : undefined;
    const info = real === undefined ? undefined : await stat(real).catch(() => undefined);
    const ok =
      real !== undefined &&
      info?.isFile() === true &&
      info.size <= MAX_EVIDENCE_BYTES &&
      EVIDENCE_TYPES.includes(extname(real).toLowerCase()) &&
      roots.some((root) => inside(root, real));
    if (!ok) {
      skipped.push(path);
      return undefined;
    }
    counter++;
    const name = `${String(counter).padStart(2, '0')}-${feature.replace(/[^\w.-]+/g, '-')}-${basename(real)}`;
    const target = join(options.destination, side, name);
    await mkdir(join(options.destination, side), { recursive: true });
    await copyFile(real, target);
    copies.set(key, target);
    return target;
  }

  const features: FeatureResult[] = [];
  for (const result of report.features) {
    const before: string[] = [];
    const after: string[] = [];
    for (const path of result.before) {
      const copied = await copy(path, 'before', result.feature);
      if (copied !== undefined) before.push(copied);
    }
    for (const path of result.after) {
      const copied = await copy(path, 'after', result.feature);
      if (copied !== undefined) after.push(copied);
    }
    features.push({ ...result, before, after });
  }
  return { report: { ...report, features }, skipped };
}
